636	    20	/**
637	    21	 * Business-day rules for registration dates.
638	    22	 *
639	    23	 * <p>A registration date must fall on a business day: any Saturday, Sunday, or
640	    24	 * {@link PublicHolidays public holiday} rolls forward to the next date that is none of
641	    25	 * those, while an ordinary weekday is left unchanged. This is the single source of truth
642	    26	 * for that adjustment, so callers never repeat it.
643	    27	 */
644	    28	public final class BusinessDay {
645	    29	
646	    30	    private BusinessDay() {
647	    31	    }
648	    32	
649	    33	    /**
650	    34	     * Roll a date forward onto a business day.
651	    35	     *
652	    36	     * @param date the date to adjust
653	    37	     * @return the earliest date on or after {@code date} that is neither a weekend nor a
654	    38	     *         public holiday
655	    39	     */
656	    40	    public static LocalDate rollForward(LocalDate date) {
657	    41	        LocalDate adjusted = date;
658	    42	        while (!isBusinessDay(adjusted)) {
659	    43	            adjusted = adjusted.plusDays(1);
660	    44	        }
661	    45	        return adjusted;
662	    46	    }
663	    47	
664	    48	    private static boolean isBusinessDay(LocalDate date) {
665	    49	        return switch (date.getDayOfWeek()) {
666	    50	            case SATURDAY, SUNDAY -> false;
667	    51	            default -> !PublicHolidays.contains(date);
668	    52	        };
669	    53	    }
670	    54	}
