741	    21	/**
742	    22	 * A coarse life-stage classification of a person: {@code MINOR} when under 18,
743	    23	 * {@code ADULT} from 18 to 64, and {@code SENIOR} at 65 or older. Owns the age
744	    24	 * boundaries so they live in one place rather than being scattered across callers.
745	    25	 */
746	    26	public enum AgeBand {
747	    27	
748	    28	    MINOR, ADULT, SENIOR;
749	    29	
750	    30	    private static final int ADULT_AGE = 18;
751	    31	    private static final int SENIOR_AGE = 65;
752	    32	
753	    33	    /**
754	    34	     * Classify the band of someone born on {@code birthDate} as of {@code asOf},
755	    35	     * using their completed age in whole years.
756	    36	     */
757	    37	    public static AgeBand asOf(LocalDate birthDate, LocalDate asOf) {
758	    38	        int years = Period.between(birthDate, asOf).getYears();
759	    39	        if (years < ADULT_AGE) {
760	    40	            return MINOR;
761	    41	        }
762	    42	        if (years < SENIOR_AGE) {
763	    43	            return ADULT;
764	    44	        }
765	    45	        return SENIOR;
766	    46	    }
767	    47	}
