    23	/**
    24	 * Builds an owner's {@code customerCode}, formatted {@code '<REGION>-<HASH8>'} where
    25	 * REGION is the owner's canonical region (see
    26	 * {@link org.springframework.samples.petclinic.model.RegionResolver}) and HASH8 is the
    27	 * first eight upper-case hexadecimal characters of the SHA-256 hash over the owner's
    28	 * normalized telephone followed by its last name. The identity is derived purely from
    29	 * the owner's own fields, carrying no sequence number.
    30	 */
    31	@Component
    32	public class CustomerCodeGenerator {
    33	
    34	    private static final int HASH_LENGTH = 8;
    35	
    36	    /**
    37	     * Build the customer code for a new owner.
    38	     *
    39	     * @param region             the owner's canonical region
    40	     * @param normalizedTelephone the owner's normalized (E.164) telephone
    41	     * @param lastName           the owner's last name
    42	     * @return the formatted customer code, e.g. {@code "NSW-1A2B3C4D"}
    43	     */
    44	    public String generate(String region, String normalizedTelephone, String lastName) {
    45	        return region + "-" + hash8(normalizedTelephone, lastName);
    46	    }
    47	
    48	    /**
    49	     * Build a customer code that does not collide with any already in use. The code is
    50	     * derived exactly as {@link #generate(String, String, String)}; when that value is
    51	     * already taken, {@code '-<n>'} is appended with the smallest {@code n} of two or more
    52	     * that yields an unused code.
    53	     *
    54	     * @param region              the owner's canonical region
    55	     * @param normalizedTelephone the owner's normalized (E.164) telephone
    56	     * @param lastName            the owner's last name
    57	     * @param isTaken             tests whether a candidate code is already in use
    58	     * @return a customer code not reported as taken by {@code isTaken}
    59	     */
    60	    public String generateUnique(String region, String normalizedTelephone, String lastName,
    61	            Predicate<String> isTaken) {
    62	        String base = generate(region, normalizedTelephone, lastName);
    63	        String candidate = base;
    64	        for (int n = 2; isTaken.test(candidate); n++) {
    65	            candidate = base + "-" + n;
    66	        }
    67	        return candidate;
    68	    }
    69	
    70	    private String hash8(String normalizedTelephone, String lastName) {
    71	        String identity = safe(normalizedTelephone) + safe(lastName);
    72	        return Sha256.hex(identity).substring(0, HASH_LENGTH).toUpperCase(Locale.ROOT);
    73	    }
    74	
    75	    private String safe(String value) {
    76	        return value == null ? "" : value;
    77	    }
    78	}
